import { useId } from "react";
import "./latchpoint-logo-anim.css";

// The "Powered by Latchpoint Studios" line in the footer (landing.powered_by, set in Site Details). The animated mark is the same one as in the footer of
// latchpointstudios.com: the ember square winds up and flies off, the outline un-draws and draws itself back on, the square lands with a squash and a glint.
// It is plain CSS keyframes (latchpoint-logo-anim.css, generated by that site's scripts/generate-logo-animation.py) and stands still for visitors who ask for
// less motion. The ember is Latchpoint's own color, not the agent's theme accent.
const EMBER = "#e8623f";
const RING = "M14.5 3.5 A6 6 0 0 1 20.5 9.5 V14.5 A6 6 0 0 1 14.5 20.5 H9.5 A6 6 0 0 1 3.5 14.5 V9.5 A6 6 0 0 1 9.5 3.5 H14.5";

function AnimatedMark({ className = "" }) {
  const uid = useId().replace(/:/g, "");
  return (
    <svg viewBox="2.5 1.2 20.3 20.3" fill="none" className={`${className} lp-logo-anim`} style={{ overflow: "visible" }} aria-hidden="true">
      <defs>
        <radialGradient id={`${uid}-glow`}>
          <stop offset="0" stopColor={EMBER} stopOpacity="0.85" />
          <stop offset="0.6" stopColor={EMBER} stopOpacity="0.3" />
          <stop offset="1" stopColor={EMBER} stopOpacity="0" />
        </radialGradient>
        <linearGradient id={`${uid}-glint`} x1="0" x2="1" y1="0" y2="0">
          <stop offset="0" stopColor="#fff" stopOpacity="0" />
          <stop offset="0.5" stopColor="#fff" stopOpacity="0.8" />
          <stop offset="1" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
        <mask id={`${uid}-mask`} maskUnits="userSpaceOnUse" x="-6" y="-6" width="36" height="36">
          <path d={RING} stroke="#fff" strokeWidth="2" strokeLinecap="round" />
          <rect x="14.8" y="1.2" width="8" height="8" rx="2.7" fill="#fff" />
        </mask>
      </defs>
      <circle className="lp-glow" cx="18.8" cy="5.2" r="10" fill={`url(#${uid}-glow)`} />
      <rect className="lp-shock lp-shock-1" x="14.7" y="1.1" width="8.2" height="8.2" rx="1.4" stroke={EMBER} strokeWidth="1" vectorEffect="non-scaling-stroke" />
      <rect className="lp-shock lp-shock-2" x="14.7" y="1.1" width="8.2" height="8.2" rx="1.4" stroke={EMBER} strokeWidth="1" vectorEffect="non-scaling-stroke" />
      <path className="lp-ring" d={RING} pathLength={1} strokeDasharray={1} stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <rect className="lp-chip" x="14.8" y="1.2" width="8" height="8" rx="2.7" fill={EMBER} />
      <circle className="lp-spark" cx="0" cy="0" r="1.5" fill={EMBER} />
      <g mask={`url(#${uid}-mask)`}>
        <g transform="rotate(45 12 12)">
          <rect className="lp-glint" x="8.5" y="-12" width="7" height="48" fill={`url(#${uid}-glint)`} />
        </g>
      </g>
    </svg>
  );
}

/** "Powered by [animated mark] Latchpoint Studios", small and quiet, in the footer's own light-on-dark colors. The mark and the name link to latchpointstudios.com. */
export default function LatchpointCredit({ className = "" }) {
  return (
    <span className={`inline-flex items-center gap-2 text-[11px] text-[var(--as-on-dark)]/45 ${className}`}>
      <span>Powered by</span>
      <a
        href="https://latchpointstudios.com"
        target="_blank"
        rel="noopener noreferrer"
        aria-label="Latchpoint Studios"
        className="inline-flex items-center gap-1.5 text-[13px] font-medium tracking-tight text-[var(--as-on-dark)]/85 transition-colors hover:text-[var(--as-on-dark)]"
      >
        <AnimatedMark className="h-[18px] w-[18px] text-[var(--as-on-dark)]" />
        <span>
          Latchpoint<span className="opacity-60"> Studios</span>
        </span>
      </a>
    </span>
  );
}
